INSERT INTO vocabulary_topics (id, name, description, created_at, updated_at)
VALUES
  (1, 'Contract and negotiation', 'Từ vựng liên quan đến hợp đồng, thỏa thuận, đàm phán, điều khoản và các giao dịch thương mại.', '2026-11-06T15:55:27.87375', '2026-11-06T01:39:26.888139'),
  (2, 'Marketing and Sales', 'Từ vựng về tiếp thị, quảng cáo, bán hàng, nghiên cứu thị trường, khách hàng và chiến lược kinh doanh.', '2026-11-06T15:57:24.986078', '2026-11-06T01:39:26.888139'),
  (3, 'Personnel and Recruitment', 'Từ vựng về nhân sự, tuyển dụng, phỏng vấn, đào tạo, quản lý nhân viên và chính sách lao động.', '2026-11-06T15:57:54.310246', '2026-11-06T01:39:26.888139'),
  (4, 'Office', 'Từ vựng về môi trường văn phòng, thiết bị, công việc hàng ngày, cuộc họp, lịch trình và giao tiếp nơi làm việc.', '2026-11-06T15:58:12.922302', '2026-11-06T01:39:26.888139'),
  (5, 'Finance', 'Từ vựng liên quan đến tài chính, ngân hàng, tài khoản, thanh toán, khoản vay, ngân sách và đầu tư.', '2026-11-06T15:58:24.70215', '2026-11-06T01:39:26.888139'),
  (6, 'Business Travel', 'Từ vựng về công tác, đặt vé, khách sạn, sân bay, phương tiện di chuyển và các chuyến đi phục vụ công việc.', '2026-11-06T15:58:41.133467', '2026-11-06T01:39:26.888139'),
  (20, 'Shipping and Logistics', 'Từ vựng về vận chuyển hàng hóa, kho bãi, xuất nhập khẩu, hải quan, bưu kiện và quản lý chuỗi cung ứng.', '2026-11-06T01:39:26.888139', '2026-11-06T01:39:26.888139'),
  (22, 'Customer Service', 'Từ vựng về chăm sóc khách hàng, tiếp nhận khiếu nại, phản hồi, bảo hành, đổi trả và hỗ trợ kỹ thuật.', '2026-11-06T01:39:26.888139', '2026-11-06T01:39:26.888139')
INSERT INTO vocabulary (id, word, meaning_vi, meaning_en, pronunciation, example_sentence, audio_url, part_of_speech, example_sentence_vi, created_at, updated_at)
VALUES
  (1, 'itinerary', 'Lịch trình chuyến đi, hành trình công tác', 'A planned route or journey; a travel document listing schedule details.', '/aɪˈtɪnərəri/', 'The executive assistant drafted a detailed itinerary for the CEO’s European roadshow.', 'https://api.dictionaryapi.dev/media/pronunciations/en/itinerary-us.mp3', 'noun', 'Trợ lý điều hành đã soạn thảo một lịch trình chi tiết cho chuyến công tác châu Âu của Tổng giám đốc.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (2, 'reservation', 'Sự đặt chỗ trước (phòng, vé máy bay)', 'An arrangement to have something kept for someone’s use at a later time.', '/ˌrezəˈveɪʃən/', 'We made a dinner reservation for eight guests at a renowned riverside seafood bistro.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=reservation', 'noun', 'Chúng tôi đã đặt chỗ ăn tối trước cho tám khách tại một quán rượu hải sản ven sông nổi tiếng.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (3, 'accommodation', 'Chỗ ở, phòng nghỉ khách sạn', 'A room, group of rooms, or building in which someone may live or stay.', '/əˌkɒməˈdeɪʃən/', 'Hotel accommodation for conference speakers is booked and covered by the organizing committee.', 'https://api.dictionaryapi.dev/media/pronunciations/en/accommodation-uk.mp3', 'noun', 'Chỗ ở khách sạn cho các diễn giả hội nghị được ban tổ chức đặt trước và chi trả toàn bộ.', '2026-11-06T15:58:57.747288', '2026-11-06T01:39:26.888139'),
  (4, 'flight', 'Chuyến bay', 'A journey made through the air, especially in an airplane.', '/flaɪt/', 'Their non-stop flight to Tokyo departs from terminal two at six in the morning.', 'https://api.dictionaryapi.dev/media/pronunciations/en/flight-au.mp3', 'noun', 'Chuyến bay thẳng đến Tokyo của họ khởi hành từ nhà ga số hai lúc sáu giờ sáng.', '2026-11-06T15:58:57.747288', '2026-11-06T01:39:26.888139'),
  (5, 'boarding', 'Việc lên máy bay/tàu', 'The action of getting on or into a ship, aircraft, or other vehicle.', '/ˈbɔːdɪŋ/', 'Gate agents announced that boarding for passenger rows twenty through thirty will begin shortly.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=boarding', 'noun', 'Nhân viên cửa lên máy bay thông báo rằng việc lên tàu cho các hàng ghế từ hai mươi đến ba mươi sẽ bắt đầu ngay sau đây.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (6, 'departure', 'Giờ khởi hành, sự xuất phát', 'The action of leaving, especially to start a journey.', '/dɪˈpɑːtʃə/', 'Passengers should arrive at the departure lounge at least ninety minutes before takeoff.', 'https://api.dictionaryapi.dev/media/pronunciations/en/departure-uk.mp3', 'noun', 'Hành khách nên đến phòng chờ khởi hành ít nhất chín mươi phút trước giờ cất cánh.', '2026-11-06T15:58:57.747288', '2026-11-06T01:39:26.888139'),
  (7, 'arrival', 'Giờ đến, sự cập bến', 'The action or process of arriving somewhere.', '/əˈraɪvəl/', 'Upon arrival at the airport, follow overhead signage toward the baggage claim hall.', 'https://api.dictionaryapi.dev/media/pronunciations/en/arrival-uk.mp3', 'noun', 'Khi đến sân bay, hãy đi theo biển chỉ dẫn trên cao hướng về sảnh nhận hành lý.', '2026-11-06T15:58:57.747288', '2026-11-06T01:39:26.888139'),
  (8, 'luggage', 'Hành lý mang theo', 'Suitcases or other bags in which to pack personal belongings for traveling.', '/ˈlʌɡɪdʒ/', 'Airlines enforce strict size and weight restrictions for carry-on luggage stored in overhead bins.', 'https://api.dictionaryapi.dev/media/pronunciations/en/luggage-uk.mp3', 'noun', 'Các hãng hàng không áp dụng những giới hạn nghiêm ngặt về kích thước và trọng lượng đối với hành lý xách tay để trong khoang trên cao.', '2026-11-06T15:58:57.747288', '2026-11-06T01:39:26.888139'),
  (9, 'baggage', 'Hành lý ký gửi', 'Suitcases and belongings taken on a trip, especially checked-in bags.', '/ˈbæɡɪdʒ/', 'Travellers can report missing or damaged checked baggage at the customer assistance counter.', 'https://api.dictionaryapi.dev/media/pronunciations/en/baggage-uk.mp3', 'noun', 'Hành khách có thể báo cáo hành lý ký gửi bị thất lạc hoặc hư hỏng tại quầy hỗ trợ khách hàng.', '2026-11-06T15:58:57.747288', '2026-11-06T01:39:26.888139'),
  (10, 'cancellation', 'Sự hủy bỏ (chuyến bay, dịch vụ)', 'The action of canceling something, such as a reservation or scheduled flight.', '/ˌkænsəˈleɪʃən/', 'The blizzard led to widespread flight cancellations across the entire northern seaboard.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=cancellation', 'noun', 'Trận bão tuyết đã dẫn đến việc hủy chuyến bay trên diện rộng dọc toàn bộ bờ biển phía bắc.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (11, 'shuttle', 'Xe buýt đưa đón tuyến ngắn', 'A bus, train, or airplane that travels regularly between two places over a short route.', '/ˈʃʌtəl/', 'The hotel provides a complimentary shuttle running to the international terminal every twenty minutes.', 'https://api.dictionaryapi.dev/media/pronunciations/en/shuttle-us.mp3', 'noun', 'Khách sạn cung cấp xe đưa đón miễn phí chạy đến nhà ga quốc tế cứ sau mỗi hai mươi phút.', '2026-11-06T15:58:57.747288', '2026-11-06T01:39:26.888139'),
  (12, 'concierge', 'Nhân viên hỗ trợ tiền sảnh khách sạn', 'A hotel employee whose job is to assist guests by booking tours, making reservations, etc.', '/kɒn.siˈeəʒ/', 'The concierge gladly arranged tickets for the sold-out classical symphony performance.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=concierge', 'noun', 'Nhân viên tiền sảnh đã vui vẻ thu xếp mua vé cho buổi biểu diễn giao hưởng cổ điển vốn đã bán hết vé.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (13, 'confirm', 'Xác nhận (đặt phòng, lịch hẹn)', 'To make certain or definitively establish the validity of a booking.', '/kənˈfɜːm/', 'Please click the link in your email to confirm your hotel reservation details.', 'https://api.dictionaryapi.dev/media/pronunciations/en/confirm-us.mp3', 'verb', 'Vui lòng nhấp vào liên kết trong email để xác nhận chi tiết đặt phòng khách sạn của bạn.', '2026-11-06T15:58:57.747288', '2026-11-06T01:39:26.888139'),
  (14, 'reception', 'Quầy tiếp tân, bàn lễ tân', 'The area in a hotel or office where visitors are greeted and attend to administrative matters.', '/rɪˈsepʃən/', 'Guests may collect their electronic room key cards directly at the twenty-four-hour reception desk.', 'https://api.dictionaryapi.dev/media/pronunciations/en/reception-us.mp3', 'noun', 'Khách có thể nhận thẻ khóa phòng điện tử trực tiếp tại quầy lễ tân phục vụ 24 giờ.', '2026-11-06T15:58:57.747288', '2026-11-06T01:39:26.888139'),
  (15, 'fare', 'Giá vé, cước xe/tàu/máy bay', 'The money a passenger on public transportation has to pay.', '/feə/', 'Train fares are discounted for seniors and students traveling during off-peak hours.', 'https://api.dictionaryapi.dev/media/pronunciations/en/fare-us.mp3', 'noun', 'Giá vé tàu hỏa được giảm giá cho người cao tuổi và học sinh sinh viên đi lại ngoài giờ cao điểm.', '2026-11-06T15:58:57.747288', '2026-11-06T01:39:26.888139'),
  (16, 'terminal', 'Nhà ga (sân bay, bến bãi)', 'A building at an airport where passengers transfer between ground transportation and flight gates.', '/ˈtɜːmɪnəl/', 'Terminal three handles all overseas long-haul flights with modern customs facilities.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=terminal', 'noun', 'Nhà ga số ba đảm nhận toàn bộ các chuyến bay đường dài ra nước ngoài với cơ sở vật chất hải quan hiện đại.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (17, 'passenger', 'Hành khách', 'A traveler on a public or private conveyance other than the driver, pilot, or crew.', '/ˈpæsɪndʒə/', 'Every passenger must present a valid passport and boarding pass before passing security.', 'https://api.dictionaryapi.dev/media/pronunciations/en/passenger-us.mp3', 'noun', 'Mỗi hành khách phải xuất trình hộ chiếu hợp lệ và thẻ lên máy bay trước khi qua cửa an ninh.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (18, 'destination', 'Điểm đến, nơi đến', 'The place to which someone or something is going or being sent.', '/ˌdestɪˈneɪʃən/', 'Da Nang has emerged as one of the most popular resort destinations for international travelers.', 'https://api.dictionaryapi.dev/media/pronunciations/en/destination-us.mp3', 'noun', 'Đà Nẵng đã nổi lên như một trong những điểm đến nghỉ dưỡng được du khách quốc tế ưa chuộng nhất.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (19, 'complimentary', 'Miễn phí kèm theo dịch vụ', 'Given or supplied free of charge.', '/ˌkɒmplɪˈmentəri/', 'The suite comes with complimentary continental breakfast and high-speed wireless internet.', 'https://api.dictionaryapi.dev/media/pronunciations/en/complimentary-us.mp3', 'adjective', 'Phòng cao cấp đi kèm bữa sáng kiểu lục địa và internet không dây tốc độ cao miễn phí.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (20, 'landmark', 'Thắng cảnh, công trình biểu tượng', 'An object or feature of a landscape or town that is easily seen and recognized from a distance.', '/ˈlændmɑːk/', 'The historical clock tower serves as an iconic landmark in the heart of the capital.', 'https://api.dictionaryapi.dev/media/pronunciations/en/landmark-uk.mp3', 'noun', 'Tòa tháp đồng hồ lịch sử đóng vai trò là một biểu tượng nổi tiếng ngay tại trung tâm thủ đô.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (21, 'excursion', 'Chuyến tham quan dã ngoại ngắn ngày', 'A short journey or trip, especially one engaged in as a leisure activity.', '/ɪkˈskɜːʃən/', 'The hotel organizes a guided cultural excursion to local artisan pottery villages every Saturday.', 'https://api.dictionaryapi.dev/media/pronunciations/en/excursion-us.mp3', 'noun', 'Khách sạn tổ chức chuyến tham quan dã ngoại có hướng dẫn viên đến các làng gốm thủ công địa phương vào thứ Bảy hàng tuần.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (22, 'commute', 'Đi lại hàng ngày giữa nhà và chỗ làm', 'To travel some distance between one’s home and place of work on a regular basis.', '/kəˈmjuːt/', 'Many professionals commute from suburban satellite towns into the central financial district.', 'https://api.dictionaryapi.dev/media/pronunciations/en/commute-uk.mp3', 'verb', 'Nhiều chuyên gia đi lại hàng ngày từ các đô thị vệ tinh vùng ngoại ô vào khu tài chính trung tâm.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (23, 'hospitality', 'Ngành khách sạn - nhà hàng, lòng hiếu khách', 'The friendly and generous reception and entertainment of guests, visitors, or strangers.', '/ˌhɒspɪˈtælɪti/', 'Vietnamese people are well known throughout the world for their warm and generous hospitality.', 'https://api.dictionaryapi.dev/media/pronunciations/en/hospitality-us.mp3', 'noun', 'Người dân Việt Nam nổi tiếng khắp thế giới nhờ lòng hiếu khách nồng hậu và hào hiệp.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (24, 'customs', 'Khu vực kiểm tra hải quan', 'The place at an airport, port, or frontier where travelers’ bags are examined for duty.', '/ˈkʌstəmz/', 'Declaring high-value foreign purchases at customs avoids severe legal penalties.', 'https://api.dictionaryapi.dev/media/pronunciations/en/customs-us.mp3', 'noun', 'Khai báo các món hàng mua ở nước ngoài có giá trị cao tại hải quan giúp tránh được các mức phạt pháp lý nặng nề.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (25, 'jetlag', 'Sự mệt mỏi do lệch múi giờ sau chuyến bay', 'Extreme tiredness and other physical effects felt by a person after a long flight across several time zones.', '/ˈdʒetlæɡ/', 'Drinking plenty of water and adjusting your sleep routine minimizes the symptoms of jetlag.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=jetlag', 'noun', 'Uống nhiều nước và điều chỉnh thói quen ngủ giúp giảm thiểu các triệu chứng mệt mỏi do lệch múi giờ.', '2026-11-06T15:58:57.747288', '2026-11-06T01:41:11.281366'),
  (26, 'budget', 'Ngân sách', 'An estimate of income and expenditure for a set period of time.', '/ˈbʌdʒɪt/', 'The marketing department managed to stay well within its allocated quarterly budget.', 'https://api.dictionaryapi.dev/media/pronunciations/en/budget-us.mp3', 'noun', 'Phòng tiếp thị đã xoay xở để duy trì mức chi tiêu nằm trong ngân sách hàng quý được phân bổ.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (27, 'audit', 'Sự kiểm toán, cuộc kiểm tra sổ sách', 'An official inspection of an individual’s or organization’s accounts.', '/ˈɔːdɪt/', 'An external accounting agency carried out an exhaustive audit of our tax declarations.', 'https://api.dictionaryapi.dev/media/pronunciations/en/audit-us.mp3', 'noun', 'Một công ty kiểm toán độc lập đã thực hiện cuộc kiểm toán toàn diện tờ khai thuế của chúng tôi.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (28, 'expense', 'Chi phí, khoản chi tiêu', 'The cost required for something; the money spent on something.', '/ɪkˈspens/', 'Travel expenses incurred on official overseas trips are reimbursed in full.', 'https://api.dictionaryapi.dev/media/pronunciations/en/expense-us.mp3', 'noun', 'Các chi phí đi lại phát sinh trong những chuyến công tác nước ngoài chính thức đều được hoàn trả đầy đủ.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (29, 'revenue', 'Doanh thu', 'Income, especially when of a company or organization and of a substantial nature.', '/ˈrevənjuː/', 'Total quarterly revenue exceeded projections thanks to robust subscription sales.', 'https://api.dictionaryapi.dev/media/pronunciations/en/revenue-us.mp3', 'noun', 'Tổng doanh thu hàng quý đã vượt dự kiến nhờ vào doanh số bán gói đăng ký tăng trưởng mạnh.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (30, 'asset', 'Tài sản', 'A useful or valuable thing, person, or quality; property owned by a person or company.', '/ˈæset/', 'Patents and proprietary software represent the company’s most valuable intellectual assets.', 'https://api.dictionaryapi.dev/media/pronunciations/en/asset-au.mp3', 'noun', 'Bằng sáng chế và phần mềm độc quyền đại diện cho những tài sản trí tuệ giá trị nhất của công ty.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (31, 'transaction', 'Giao dịch thương mại, ngân hàng', 'An instance of buying or selling something; a business deal.', '/trænˈzækʃən/', 'The payment gateway ensures every electronic transaction is encrypted and verified.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=transaction', 'noun', 'Cổng thanh toán đảm bảo mọi giao dịch điện tử đều được mã hóa và xác thực.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (32, 'balance', 'Số dư tài khoản', 'An amount of money remaining in an account after other sums have been debited or credited.', '/ˈbæləns/', 'Customers can view their account balance by logging into the online banking application.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=balance', 'noun', 'Khách hàng có thể xem số dư tài khoản của mình bằng cách đăng nhập vào ứng dụng ngân hàng trực tuyến.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (33, 'dividend', 'Cổ tức', 'A sum of money paid regularly by a company to its shareholders out of its profits.', '/ˈdɪvɪdend/', 'Shareholders expressed pleasure after the board declared a ten percent cash dividend.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=dividend', 'noun', 'Các cổ đông bày tỏ sự hài lòng sau khi hội đồng quản trị công bố mức chi trả cổ tức bằng tiền mặt mười phần trăm.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (34, 'interest', 'Tiền lãi, lãi suất', 'Money paid regularly at a particular rate for the use of money lent.', '/ˈɪntrəst/', 'The commercial bank offers a competitive interest rate on long-term fixed deposits.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=interest', 'noun', 'Ngân hàng thương mại đưa ra mức lãi suất cạnh tranh cho các khoản tiền gửi kỳ hạn dài.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (35, 'mortgage', 'Khoản vay thế chấp (bất động sản)', 'A legal agreement by which a bank or creditor lends money at interest in exchange for real estate title.', '/ˈmɔːɡɪdʒ/', 'They secured a thirty-year fixed-rate mortgage to acquire their downtown commercial building.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=mortgage', 'noun', 'Họ đã vay được một khoản thế chấp lãi suất cố định ba mươi năm để mua tòa nhà thương mại tại trung tâm thành phố.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (36, 'deficit', 'Sự thâm hụt, số tiền thiếu hụt', 'The amount by which something, especially a sum of money, is too small.', '/ˈdefɪsɪt/', 'The administration introduced cost-saving policies to narrow the operational budget deficit.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=deficit', 'noun', 'Chính quyền đã đưa ra các chính sách tiết kiệm chi phí để thu hẹp mức thâm hụt ngân sách hoạt động.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (37, 'surplus', 'Thặng dư, số tiền dôi ra', 'An amount of something left over when requirements have been met; an excess of production.', '/ˈsɜːpləs/', 'The firm invested its annual trade surplus into cutting-edge research and development.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=surplus', 'noun', 'Công ty đã đầu tư khoản thặng dư thương mại hàng năm của mình vào nghiên cứu và phát triển tiên tiến.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (38, 'financial', 'Thuộc về tài chính', 'Relating to finance or monetary matters.', '/faɪˈnænʃəl/', 'Sound financial planning is essential for navigating turbulent economic periods.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=financial', 'adjective', 'Kế hoạch tài chính lành mạnh là điều thiết yếu để vượt qua những giai đoạn kinh tế biến động.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (39, 'statement', 'Bản sao kê tài khoản, báo cáo tài chính', 'A document setting out items of financial data or account records.', '/ˈsteɪtmənt/', 'Bank customers receive an electronic billing statement at the start of each month.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=statement', 'noun', 'Khách hàng của ngân hàng nhận được bản sao kê thanh toán điện tử vào đầu mỗi tháng.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (40, 'currency', 'Tiền tệ', 'A system of money in general use in a particular country.', '/ˈkʌrənsi/', 'Fluctuations in international foreign currency exchange rates impacted export profits.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=currency', 'noun', 'Sự biến động của tỷ giá hối đoái tiền tệ quốc tế đã tác động đến lợi nhuận xuất khẩu.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (41, 'deposit', 'Tiền gửi, tiền đặt cọc', 'A sum of money placed or kept in a bank account, usually to gain interest.', '/dɪˈpɒzɪt/', 'Tenants must leave a two-month security deposit prior to collecting the apartment keys.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=deposit', 'noun', 'Khách thuê phải nộp khoản tiền đặt cọc bảo đảm bằng hai tháng tiền nhà trước khi nhận chìa khóa căn hộ.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (42, 'withdraw', 'Rút tiền (khỏi tài khoản)', 'To remove or take away money from a bank account.', '/wɪðˈdrɔː/', 'Account holders may withdraw up to one thousand dollars daily from automated teller machines.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=withdraw', 'verb', 'Chủ tài khoản có thể rút tối đa một nghìn đô la mỗi ngày từ các cây ATM.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (43, 'account', 'Tài khoản ngân hàng/kế toán', 'A record of financial expenditure and receipts relating to a particular period or purpose.', '/əˈkaʊnt/', 'She opened a corporate checking account dedicated exclusively to payroll processing.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=account', 'noun', 'Cô ấy đã mở một tài khoản thanh toán doanh nghiệp dành riêng cho việc xử lý chi trả lương.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (44, 'loan', 'Khoản tiền vay', 'A thing that is borrowed, especially a sum of money that is expected to be paid back with interest.', '/ləʊn/', 'The commercial bank approved a low-interest equipment loan for the agricultural cooperative.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=loan', 'noun', 'Ngân hàng thương mại đã duyệt một khoản vay mua máy móc lãi suất thấp cho hợp tác xã nông nghiệp.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (45, 'invoice', 'Hóa đơn thanh toán', 'A list of goods sent or services provided, with a statement of the sum due for these.', '/ˈɪnvɔɪs/', 'The vendor issued an itemized invoice detailing materials, labor, and applicable sales tax.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=invoice', 'noun', 'Nhà cung cấp đã phát hành một hóa đơn ghi rõ từng khoản chi tiết vật tư, nhân công và thuế bán hàng áp dụng.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (46, 'receipt', 'Biên lai, biên nhận thu tiền', 'A written or printed acknowledgment that a specified article or sum of money has been received.', '/rɪˈsiːt/', 'Always retain your purchase receipt in case an exchange or refund is required.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=receipt', 'noun', 'Luôn giữ lại biên lai mua hàng của bạn phòng trường hợp cần đổi hàng hoặc hoàn tiền.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (47, 'penalty', 'Khoản tiền phạt, hình phạt vi phạm', 'A punishment imposed for breaking a law, rule, or contract.', '/ˈpenəlti/', 'Late bill payments incur a five percent financial penalty after the initial grace period.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=penalty', 'noun', 'Việc thanh toán hóa đơn muộn sẽ phải chịu mức phạt tài chính năm phần trăm sau thời gian gia hạn ban đầu.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (48, 'profitable', 'Có lãi, sinh lời', 'Yielding profit or financial gain.', '/ˈprɒfɪtəbəl/', 'Expanding into subscription software proved to be a highly profitable strategic move.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=profitable', 'adjective', 'Mở rộng sang mảng phần mềm thuê bao đã chứng minh là một bước đi chiến lược mang lại lợi nhuận cao.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (49, 'investment', 'Khoản đầu tư, sự đầu tư', 'The action or process of investing money for profit.', '/ɪnˈvestmənt/', 'The venture capital fund made a substantial initial investment in solar energy tech.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=investment', 'noun', 'Quỹ đầu tư mạo hiểm đã thực hiện một khoản đầu tư ban đầu đáng kể vào công nghệ năng lượng mặt trời.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (50, 'reconcile', 'Đối soát, đối chiếu số liệu kế toán', 'To make one account consistent with another by comparing balances and entries.', '/ˈrekənsaɪl/', 'Accountants must reconcile bank statements against internal ledger entries each month.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=reconcile', 'verb', 'Các kế toán viên phải đối soát bản sao kê ngân hàng với các bút toán sổ cái nội bộ mỗi tháng.', '2026-11-06T16:05:06.736056', '2026-11-06T01:41:11.281366'),
  (51, 'colleague', 'Đồng nghiệp', 'A person with whom one works in a profession or business.', '/ˈkɒliːɡ/', 'She collaborated closely with a colleague from the design team to finish the blueprint.', 'https://api.dictionaryapi.dev/media/pronunciations/en/colleague-us.mp3', 'noun', 'Cô ấy đã hợp tác chặt chẽ với một đồng nghiệp từ nhóm thiết kế để hoàn thành bản thiết kế.', '2026-11-06T16:05:28.262129', '2026-11-06T01:39:26.888139'),
  (52, 'deadline', 'Hạn chót, thời hạn hoàn thành', 'The latest time or date by which something should be completed.', '/ˈdedlaɪn/', 'The project manager reminded the crew that the proposal deadline is noon on Friday.', 'https://api.dictionaryapi.dev/media/pronunciations/en/deadline-uk.mp3', 'noun', 'Trưởng dự án nhắc nhở toàn đội rằng hạn chót nộp bản đề xuất là 12 giờ trưa thứ Sáu.', '2026-11-06T16:05:28.262129', '2026-11-06T01:39:26.888139'),
  (53, 'schedule', 'Lịch trình, thời gian biểu', 'A plan for carrying out a process or procedure, giving lists of intended events and times.', '/ˈʃedjuːl/', 'Due to unexpected renovations, our training seminar schedule was pushed back one week.', 'https://api.dictionaryapi.dev/media/pronunciations/en/schedule-au.mp3', 'noun', 'Do việc sửa chữa đột xuất, lịch trình hội thảo đào tạo của chúng tôi đã bị dời lại một tuần.', '2026-11-06T16:05:28.262129', '2026-11-06T01:39:26.888139'),
  (54, 'memo', 'Thông báo nội bộ, giác thư', 'A written message in business, diplomacy, or state affairs.', '/ˈmeməʊ/', 'The human resources director circulated an internal memo about revised overtime regulations.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=memo', 'noun', 'Giám đốc nhân sự đã lưu hành một thông báo nội bộ về các quy định làm thêm giờ sửa đổi.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (55, 'agenda', 'Chương trình nghị sự, nội dung cuộc họp', 'A list of items to be discussed at a formal meeting.', '/əˈdʒendə/', 'The board secretary sent out the meeting agenda three days prior to the conference.', 'https://api.dictionaryapi.dev/media/pronunciations/en/agenda-us.mp3', 'noun', 'Thư ký hội đồng quản trị đã gửi chương trình cuộc họp ba ngày trước hội nghị.', '2026-11-06T16:05:28.262129', '2026-11-06T01:39:26.888139'),
  (56, 'equipment', 'Trang thiết bị, máy móc', 'The necessary items for a particular purpose or activity.', '/ɪˈkwɪpmənt/', 'The modern laboratory was outfitted with sophisticated scientific testing equipment.', 'https://api.dictionaryapi.dev/media/pronunciations/en/equipment-us.mp3', 'noun', 'Phòng thí nghiệm hiện đại đã được trang bị thiết bị thử nghiệm khoa học tinh vi.', '2026-11-06T16:05:28.262129', '2026-11-06T01:39:26.888139'),
  (57, 'inventory', 'Hàng tồn kho, sự kiểm kê', 'A complete list of items such as goods and materials in stock.', '/ˈɪnvəntri/', 'Warehouse clerks perform a quarterly inventory check to verify stock counts.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=inventory', 'noun', 'Các nhân viên kho thực hiện việc kiểm kê hàng quý để xác thực số lượng hàng tồn kho.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (58, 'stationery', 'Văn phòng phẩm', 'Writing materials and other office supplies such as envelopes and pens.', '/ˈsteɪʃənəri/', 'The administrative assistant placed a bulk stationery order for notebooks and printer toner.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=stationery', 'noun', 'Trợ lý hành chính đã đặt một đơn hàng văn phòng phẩm số lượng lớn gồm sổ tay và mực máy in.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (59, 'procedure', 'Quy trình, thủ tục', 'An established or official way of doing something.', '/prəˈsiːdʒə/', 'All employees must follow the standard safety procedure when entering the server room.', 'https://api.dictionaryapi.dev/media/pronunciations/en/procedure-us.mp3', 'noun', 'Tất cả nhân viên phải tuân theo quy trình an toàn tiêu chuẩn khi bước vào phòng máy chủ.', '2026-11-06T16:05:28.262129', '2026-11-06T01:39:26.888139'),
  (60, 'delegate', 'Ủy thác, giao phó công việc', 'To entrust a task or responsibility to another person.', '/ˈdelɪɡeɪt/', 'Effective managers know how to delegate routine tasks so they can focus on strategy.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=delegate', 'verb', 'Những nhà quản lý hiệu quả biết cách giao phó các công việc thường nhật để có thể tập trung vào chiến lược.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (61, 'conference', 'Hội nghị, hội thảo chuyên đề', 'A formal meeting of people with a shared interest, typically over several days.', '/ˈkɒnfərəns/', 'The annual medical conference drew over five thousand delegates from across the globe.', 'https://api.dictionaryapi.dev/media/pronunciations/en/conference-uk.mp3', 'noun', 'Hội nghị y khoa thường niên đã thu hút hơn năm nghìn đại biểu từ khắp nơi trên thế giới.', '2026-11-06T16:05:28.262129', '2026-11-06T01:39:26.888139'),
  (62, 'attend', 'Tham dự, có mặt', 'To be present at an event, meeting, or function.', '/əˈtend/', 'Department heads are required to attend the budget briefing scheduled for tomorrow morning.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=attend', 'verb', 'Các trưởng bộ phận được yêu cầu tham dự buổi báo cáo ngân sách dự kiến diễn ra vào sáng mai.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (63, 'supervise', 'Giám sát, quản lý', 'To observe and direct the execution of a task, project, or activity.', '/ˈsuːpəvaɪz/', 'A senior civil engineer was hired to supervise the bridge construction project.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=supervise', 'verb', 'Một kỹ sư xây dựng kỳ cựu đã được thuê để giám sát dự án xây dựng cây cầu.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (64, 'assignment', 'Nhiệm vụ được phân công', 'A task or piece of work assigned to someone as part of a job or course of study.', '/əˈsaɪnmənt/', 'Completing the market research assignment took the consulting team three full weeks.', 'https://api.dictionaryapi.dev/media/pronunciations/en/assignment-us.mp3', 'noun', 'Việc hoàn thành nhiệm vụ nghiên cứu thị trường đã làm nhóm tư vấn mất trọn ba tuần.', '2026-11-06T16:05:28.262129', '2026-11-06T01:39:26.888139'),
  (65, 'report', 'Báo cáo, bản tường trình', 'An account given of a particular matter, especially in the form of an official document.', '/rɪˈpɔːt/', 'The annual financial report demonstrated a solid twenty percent increase in net profits.', 'https://api.dictionaryapi.dev/media/pronunciations/en/report-us.mp3', 'noun', 'Bản báo cáo tài chính hàng năm đã chứng minh sự gia tăng vững chắc hai mươi phần trăm lợi nhuận ròng.', '2026-11-06T16:05:28.262129', '2026-11-06T01:39:26.888139'),
  (66, 'submit', 'Nộp, trình đệ (tài liệu, hồ sơ)', 'To present a proposal, document, or application to a person or body for consideration.', '/səbˈmɪt/', 'Please submit your quarterly expense receipts to accounting before the end of the month.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=submit', 'verb', 'Vui lòng nộp biên lai chi phí hàng quý của bạn cho phòng kế toán trước cuối tháng.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (67, 'revise', 'Chỉnh sửa, duyệt lại', 'To re-examine and make alterations to written or printed work.', '/rɪˈvaɪz/', 'The marketing team had to revise the brochure text following client feedback.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=revise', 'verb', 'Nhóm tiếp thị đã phải chỉnh sửa nội dung tập tài liệu theo phản hồi của khách hàng.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (68, 'document', 'Tài liệu, văn kiện', 'A piece of written, printed, or electronic matter that provides information or evidence.', '/ˈdɒkjʊmənt/', 'Please keep a scanned backup copy of this legal document in secure cloud storage.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=document', 'noun', 'Vui lòng lưu một bản sao lưu quét của tài liệu pháp lý này trong bộ nhớ đám mây an toàn.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (69, 'duplicate', 'Bản sao y, bản nhân đôi', 'One of two or more identical things; an exact copy.', '/ˈdjuːplɪkət/', 'The office manager made an official duplicate of the lease for the landlord’s records.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=duplicate', 'noun', 'Quản lý văn phòng đã làm một bản sao chính thức của hợp đồng thuê để lưu hồ sơ của chủ nhà.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (70, 'shred', 'Xén vụn, tiêu hủy tài liệu mật', 'To tear or cut into shreds; to destroy confidential papers securely.', '/ʃred/', 'Strict privacy policies require workers to shred all documents containing customer details.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=shred', 'verb', 'Các chính sách bảo mật nghiêm ngặt yêu cầu nhân viên phải tiêu hủy vụn toàn bộ tài liệu chứa thông tin chi tiết của khách hàng.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (71, 'facility', 'Cơ sở vật chất, địa điểm tiện ích', 'A place, amenity, or piece of equipment provided for a particular purpose.', '/fəˈsɪlɪti/', 'The company opened a state-of-the-art research facility just outside the capital.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=facility', 'noun', 'Công ty đã khánh thành một cơ sở nghiên cứu hiện đại bậc nhất ngay ngoại ô thủ đô.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (72, 'maintain', 'Duy trì, bảo trì, bảo dưỡng', 'To cause or enable a condition or state of affairs to continue; to keep equipment in good condition.', '/meɪnˈteɪn/', 'Technicians visit monthly to maintain the commercial air conditioning units.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=maintain', 'verb', 'Các kỹ thuật viên đến hàng tháng để bảo dưỡng các cụm máy điều hòa không khí thương mại.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (73, 'distribute', 'Phân phối, phân phát', 'To give shares of something; to hand out or deliver items to a number of people.', '/dɪˈstrɪbjuːt/', 'Volunteers will distribute the updated safety handbooks during orientation.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=distribute', 'verb', 'Các tình nguyện viên sẽ phân phát sổ tay an toàn cập nhật trong buổi định hướng.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (74, 'priority', 'Sự ưu tiên hàng đầu', 'The fact or condition of being regarded or treated as more important than others.', '/praɪˈɒrɪti/', 'Resolving network connectivity bugs is currently our highest technical priority.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=priority', 'noun', 'Giải quyết các lỗi kết nối mạng hiện là ưu tiên kỹ thuật cao nhất của chúng tôi.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (75, 'correspondence', 'Thư từ giao dịch, liên lạc công văn', 'Communication by exchanging letters, emails, or official messages.', '/ˌkɒrɪˈspɒndəns/', 'All official correspondence regarding the merger must go through the legal affairs office.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=correspondence', 'noun', 'Mọi thư từ công văn chính thức liên quan đến vụ sáp nhập đều phải thông qua văn phòng pháp chế.', '2026-11-06T16:05:28.262129', '2026-11-06T01:41:11.281366'),
  (76, 'applicant', 'Người nộp đơn xin việc, ứng viên', 'A person who makes a formal application for something, especially a job.', '/ˈæplɪkənt/', 'Over three hundred applicants submitted resumes for the junior developer role.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=applicant', 'noun', 'Hơn ba trăm ứng viên đã nộp hồ sơ xin việc cho vị trí lập trình viên sơ cấp.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (77, 'candidate', 'Ứng viên tiềm năng', 'A person who applies for a job or is nominated for election and assessment.', '/ˈkændɪdət/', 'The hiring committee selected the most qualified candidate after multiple interview rounds.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=candidate', 'noun', 'Hội đồng tuyển dụng đã chọn ra ứng viên có trình độ tốt nhất sau nhiều vòng phỏng vấn.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (78, 'recruit', 'Tuyển dụng, chiêu mộ nhân sự', 'To enlist someone in an organization, company, or cause.', '/rɪˈkruːt/', 'Our enterprise travels to prestigious universities to recruit talented engineering graduates.', 'https://api.dictionaryapi.dev/media/pronunciations/en/recruit-uk.mp3', 'verb', 'Doanh nghiệp chúng tôi đến các trường đại học uy tín để tuyển dụng các tân kỹ sư tài năng.', '2026-11-06T16:05:39.462053', '2026-11-06T01:39:26.888139'),
  (79, 'interview', 'Buổi phỏng vấn', 'A meeting of people face to face, especially for consultation or employment assessment.', '/ˈɪntəvjuː/', 'The final round interview will be conducted directly by the vice president.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=interview', 'noun', 'Buổi phỏng vấn vòng cuối cùng sẽ do chính phó chủ tịch trực tiếp thực hiện.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (80, 'qualification', 'Bằng cấp, năng lực, phẩm chất đáp ứng công việc', 'A quality or accomplishment that makes someone suitable for a particular job or activity.', '/ˌkwɒlɪfɪˈkeɪʃən/', 'Fluency in two foreign languages is a mandatory qualification for this diplomatic post.', 'https://api.dictionaryapi.dev/media/pronunciations/en/qualification-uk.mp3', 'noun', 'Thành thạo hai ngoại ngữ là một bằng cấp/tiêu chuẩn bắt buộc cho vị trí ngoại giao này.', '2026-11-06T16:05:39.462053', '2026-11-06T01:39:26.888139'),
  (81, 'resume', 'Sơ yếu lý lịch, hồ sơ xin việc (CV)', 'A brief account of a person’s education, qualifications, and previous experience.', '/ˈrezjʊmeɪ/', 'Please ensure your resume includes current contact details and relevant work history.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=resume', 'noun', 'Vui lòng đảm bảo hồ sơ xin việc của bạn có đầy đủ thông tin liên hệ hiện tại và lịch sử làm việc liên quan.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (82, 'hire', 'Thuê, tuyển dụng nhân viên', 'To employ someone for wages or a salary.', '/ˈhaɪə/', 'The software division decided to hire four additional backend engineers immediately.', 'https://api.dictionaryapi.dev/media/pronunciations/en/hire-us.mp3', 'verb', 'Bộ phận phần mềm đã quyết định tuyển dụng thêm bốn kỹ sư backend ngay lập tức.', '2026-11-06T16:05:39.462053', '2026-11-06T01:39:26.888139'),
  (83, 'salary', 'Lương cố định hàng tháng/năm', 'A fixed regular payment made by an employer to an employee.', '/ˈsæləri/', 'The starting salary is highly competitive and adjusted annually according to performance.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=salary', 'noun', 'Mức lương khởi điểm rất cạnh tranh và được điều chỉnh hàng năm theo kết quả công việc.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (84, 'benefit', 'Quyền lợi, phúc lợi nhân viên', 'An advantage or profit gained from something; extra payment or perks given to staff.', '/ˈbenɪfɪt/', 'Corporate benefits include comprehensive health coverage, paid leave, and retirement contributions.', 'https://api.dictionaryapi.dev/media/pronunciations/en/benefit-us.mp3', 'noun', 'Các phúc lợi doanh nghiệp bao gồm bảo hiểm sức khỏe toàn diện, nghỉ phép có lương và đóng góp quỹ hưu trí.', '2026-11-06T16:05:39.462053', '2026-11-06T01:39:26.888139'),
  (85, 'probationary', 'Thử việc, tập sự', 'Relating to a process of testing someone’s character or abilities before permanent hire.', '/prəˈbeɪʃənəri/', 'New hires must successfully complete a three-month probationary period.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=probationary', 'adjective', 'Nhân viên mới phải hoàn thành xuất sắc thời gian thử việc ba tháng.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (86, 'experience', 'Kinh nghiệm làm việc', 'Practical contact with and observation of facts or events over time.', '/ɪkˈspɪəriəns/', 'Applicants should have at least five years of managerial experience in banking.', 'https://api.dictionaryapi.dev/media/pronunciations/en/experience-uk.mp3', 'noun', 'Ứng viên nên có ít nhất năm năm kinh nghiệm quản lý trong lĩnh vực ngân hàng.', '2026-11-06T16:05:39.462053', '2026-11-06T01:39:26.888139'),
  (87, 'position', 'Vị trí công tác, chức vụ', 'A job or paid post of employment.', '/pəˈzɪʃən/', 'She accepted an executive position heading the corporate communications division.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=position', 'noun', 'Cô ấy đã nhận một vị trí điều hành đứng đầu bộ phận truyền thông doanh nghiệp.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (88, 'trainee', 'Thực tập sinh, học viên tập sự', 'A person undergoing training for a particular job or profession.', '/treɪˈniː/', 'Every management trainee rotates through marketing, finance, and logistics departments.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=trainee', 'noun', 'Mỗi học viên quản trị tập sự đều luân chuyển qua các phòng ban tiếp thị, tài chính và hậu cần.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (89, 'mentor', 'Người hướng dẫn, cố vấn', 'An experienced and trusted adviser who helps train a junior colleague.', '/ˈmentɔː/', 'Each newcomer is assigned a senior mentor to facilitate workplace integration.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=mentor', 'noun', 'Mỗi người mới đều được phân công một người cố vấn cấp cao để tạo thuận lợi cho việc hòa nhập công sở.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (90, 'resign', 'Từ chức, thôi việc', 'To voluntarily leave a job or other position.', '/rɪˈzaɪn/', 'The chief financial officer chose to resign to pursue personal entrepreneurial ventures.', 'https://api.dictionaryapi.dev/media/pronunciations/en/resign-1-uk.mp3', 'verb', 'Giám đốc tài chính đã chọn từ chức để theo đuổi các dự án khởi nghiệp cá nhân.', '2026-11-06T16:05:39.462053', '2026-11-06T01:39:26.888139'),
  (91, 'retire', 'Nghỉ hưu', 'To leave one’s job and cease to work, typically on reaching normal working age.', '/rɪˈtaɪə/', 'After thirty-five dedicated years with the firm, Mr. Davies plans to retire in December.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=retire', 'verb', 'Sau ba mươi lăm năm cống hiến cho công ty, ông Davies dự định nghỉ hưu vào tháng Mười Hai.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (92, 'evaluation', 'Sự đánh giá (năng lực, hiệu quả công việc)', 'The making of a judgment about the amount, number, or value of something.', '/ɪˌvæljʊˈeɪʃən/', 'Annual staff evaluations determine eligibility for bonuses and career promotions.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=evaluation', 'noun', 'Các đợt đánh giá nhân viên thường niên quyết định điều kiện nhận thưởng và thăng tiến nghề nghiệp.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (93, 'reference', 'Thư giới thiệu, người chứng nhận lý lịch', 'A recommendation from a person who can vouch for someone’s character or ability.', '/ˈrefərəns/', 'The human resources department contacted three former employers as professional references.', 'https://api.dictionaryapi.dev/media/pronunciations/en/reference-us.mp3', 'noun', 'Phòng nhân sự đã liên hệ với ba người sử dụng lao động cũ để làm người chứng nhận nghề nghiệp.', '2026-11-06T16:05:39.462053', '2026-11-06T01:39:26.888139'),
  (94, 'vacancy', 'Vị trí còn trống (cần tuyển)', 'An unoccupied position or job available within an enterprise.', '/ˈveɪkənsi/', 'We posted an urgent vacancy notice for an experienced certified accountant.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=vacancy', 'noun', 'Chúng tôi đã đăng thông báo tuyển gấp vị trí còn trống cho một kế toán viên có chứng chỉ và kinh nghiệm.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (95, 'employment', 'Việc làm, sự tuyển dụng', 'The state of having paid work, or the act of employing staff.', '/ɪmˈplɔɪmənt/', 'The new regional factory created stable employment for over eight hundred residents.', 'https://api.dictionaryapi.dev/media/pronunciations/en/employment-us.mp3', 'noun', 'Nhà máy mới trong khu vực đã tạo việc làm ổn định cho hơn tám trăm cư dân.', '2026-11-06T16:05:39.462053', '2026-11-06T01:39:26.888139'),
  (96, 'compensation', 'Tiền bồi thường, thù lao chi trả', 'Money awarded to someone as recompense for loss, injury, or work performed.', '/ˌkɒmpenˈseɪʃən/', 'The executive compensation package includes stock options and relocation assistance.', 'https://api.dictionaryapi.dev/media/pronunciations/en/compensation-us.mp3', 'noun', 'Gói thù lao dành cho cấp quản trị bao gồm quyền mua cổ phiếu và hỗ trợ chi phí chuyển chỗ ở.', '2026-11-06T16:05:39.462053', '2026-11-06T01:39:26.888139'),
  (97, 'dismiss', 'Sa thải, cho thôi việc', 'To discharge an employee from employment or service.', '/dɪsˈmɪs/', 'The supervisor warned that repeated unexcused absences would lead management to dismiss the worker.', 'https://api.dictionaryapi.dev/media/pronunciations/en/dismiss-au.mp3', 'verb', 'Người giám sát cảnh báo rằng việc vắng mặt không phép nhiều lần sẽ khiến ban quản lý sa thải công nhân đó.', '2026-11-06T16:05:39.462053', '2026-11-06T01:39:26.888139'),
  (98, 'eligibility', 'Đủ điều kiện, tư cách hợp lệ', 'The state of having the right qualifications to do or receive something.', '/ˌelɪdʒəˈbɪlɪti/', 'Eligibility for parental leave requires at least twelve months of uninterrupted service.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=eligibility', 'noun', 'Điều kiện đủ để được nghỉ phép thai sản đòi hỏi ít nhất mười hai tháng công tác liên tục.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (99, 'payroll', 'Bảng lương, quỹ lương của công ty', 'The total amount of wages and salaries paid by a company to its staff.', '/ˈpeɪrəʊl/', 'Direct deposit ensures all salaries are credited to employee bank accounts on payroll day.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=payroll', 'noun', 'Hình thức chuyển khoản trực tiếp đảm bảo toàn bộ tiền lương được ghi có vào tài khoản ngân hàng của nhân viên vào ngày trả lương.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366'),
  (100, 'apprentice', 'Người học việc', 'A person who is learning a trade from a skilled employer, having agreed to work for a fixed period.', '/əˈprentɪs/', 'The senior electrician taught the apprentice how to read complex industrial wiring diagrams.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=apprentice', 'noun', 'Người thợ điện kỳ cựu đã dạy người học việc cách đọc các sơ đồ đấu dây công nghiệp phức tạp.', '2026-11-06T16:05:39.462053', '2026-11-06T01:41:11.281366')
INSERT INTO vocabulary (id, word, meaning_vi, meaning_en, pronunciation, example_sentence, audio_url, part_of_speech, example_sentence_vi, created_at, updated_at)
VALUES
  (101, 'agreement', 'Sự thỏa thuận, hợp đồng thỏa thuận', 'A negotiated and typically legally binding arrangement between parties.', '/əˈɡriːmənt/', 'Both parties signed the agreement after two weeks of intense negotiation.', 'https://api.dictionaryapi.dev/media/pronunciations/en/agreement-us.mp3', 'noun', 'Cả hai bên đã ký thỏa thuận sau hai tuần đàm phán căng thẳng.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (102, 'contract', 'Hợp đồng, khế ước giao kèo', 'A written or spoken agreement that is intended to be enforceable by law.', '/ˈkɒntrækt/', 'The lawyer carefully reviewed every clause of the employment contract.', 'https://api.dictionaryapi.dev/media/pronunciations/en/contract-1-uk.mp3', 'noun', 'Luật sư đã xem xét kỹ lưỡng từng điều khoản của hợp đồng lao động.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (103, 'negotiate', 'Đàm phán, thương lượng', 'To discuss something in order to reach a formal agreement.', '/nɪˈɡəʊʃieɪt/', 'Our sales director will negotiate a better price with the supplier tomorrow.', 'https://api.dictionaryapi.dev/media/pronunciations/en/negotiate-au.mp3', 'verb', 'Giám đốc bán hàng của chúng tôi sẽ thương lượng mức giá tốt hơn với nhà cung cấp vào ngày mai.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (104, 'obligation', 'Nghĩa vụ, bổn phận ràng buộc', 'An act or course of action to which a person is morally or legally bound.', '/ˌɒblɪˈɡeɪʃən/', 'The tenant has a legal obligation to pay the monthly rent on time.', 'https://api.dictionaryapi.dev/media/pronunciations/en/obligation-us.mp3', 'noun', 'Người thuê nhà có nghĩa vụ pháp lý phải trả tiền thuê hàng tháng đúng hạn.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (105, 'party', 'Bên tham gia (hợp đồng, thỏa thuận)', 'A person or group taking part in a legal transaction or agreement.', '/ˈpɑːti/', 'Neither party can modify the terms without written consent from the other.', 'https://api.dictionaryapi.dev/media/pronunciations/en/party-ca.mp3', 'noun', 'Không bên nào được sửa đổi các điều khoản mà không có sự đồng ý bằng văn bản của bên kia.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (106, 'provision', 'Điều khoản, điều kiện quy định', 'A condition or requirement in a legal document or agreement.', '/prəˈvɪʒən/', 'The contract includes a special provision for early termination fees.', 'https://api.dictionaryapi.dev/media/pronunciations/en/provision-us.mp3', 'noun', 'Hợp đồng bao gồm một điều khoản đặc biệt về phí chấm dứt trước hạn.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (107, 'resolve', 'Giải quyết, xử lý (tranh chấp, vấn đề)', 'To settle or find a solution to a problem or dispute.', '/rɪˈzɒlv/', 'Management hopes to resolve the contract dispute before taking legal action.', 'https://api.dictionaryapi.dev/media/pronunciations/en/resolve-1-us.mp3', 'verb', 'Ban quản lý hy vọng giải quyết tranh chấp hợp đồng trước khi thực hiện hành động pháp lý.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (108, 'specific', 'Cụ thể, rõ ràng, chi tiết', 'Clearly defined or identified; precise and detailed.', '/spəˈsɪfɪk/', 'Please state your specific requirements regarding product specifications in writing.', 'https://api.dictionaryapi.dev/media/pronunciations/en/specific-us.mp3', 'adjective', 'Vui lòng nêu rõ các yêu cầu cụ thể của bạn về thông số sản phẩm bằng văn bản.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (109, 'terminate', 'Chấm dứt, kết thúc (hợp đồng, dự án)', 'To bring something to an end or to conclude a contract prematurely.', '/ˈtɜːmɪneɪt/', 'The company decided to terminate the partnership due to persistent shipping delays.', 'https://api.dictionaryapi.dev/media/pronunciations/en/terminate-uk.mp3', 'verb', 'Công ty quyết định chấm dứt quan hệ đối tác do sự chậm trễ giao hàng liên tục.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (110, 'abide', 'Tuân theo, làm theo (luật lệ, thỏa thuận)', 'To accept or act in accordance with a rule, decision, or recommendation.', '/əˈbaɪd/', 'All contractors must abide by the safety regulations set by the site manager.', 'https://api.dictionaryapi.dev/media/pronunciations/en/abide-us.mp3', 'verb', 'Tất cả các nhà thầu phải tuân theo các quy định an toàn do quản lý công trường đặt ra.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (111, 'assure', 'Cam đoan, đảm bảo chắc chắn', 'To tell someone something positively to dispel any doubts.', '/əˈʃʊə/', 'The supplier assured us that all orders would be dispatched by Friday afternoon.', 'https://api.dictionaryapi.dev/media/pronunciations/en/assure-us.mp3', 'verb', 'Nhà cung cấp đã đảm bảo với chúng tôi rằng toàn bộ đơn hàng sẽ được gửi đi trước chiều thứ Sáu.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (112, 'cancel', 'Hủy bỏ, bãi bỏ', 'To decide that an agreed or planned event will not take place.', '/ˈkænsəl/', 'You may cancel the subscription at any time without paying any extra charges.', 'https://api.dictionaryapi.dev/media/pronunciations/en/cancel-au.mp3', 'verb', 'Bạn có thể hủy đăng ký bất cứ lúc nào mà không phải trả thêm bất kỳ khoản phí nào.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (113, 'determine', 'Xác định, quyết định', 'To ascertain or establish exactly by research or calculation.', '/dɪˈtɜːmɪn/', 'A committee will meet next Monday to determine the final budget for the marketing project.', 'https://api.dictionaryapi.dev/media/pronunciations/en/determine-ca.mp3', 'verb', 'Một ủy ban sẽ họp vào thứ Hai tới để xác định ngân sách cuối cùng cho dự án tiếp thị.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (114, 'engage', 'Tham gia, gắn kết, cam kết', 'To participate or become involved in something.', '/ɪnˈɡeɪdʒ/', 'Our enterprise intends to engage in long-term trade relations with international partners.', 'https://api.dictionaryapi.dev/media/pronunciations/en/engage-us.mp3', 'verb', 'Doanh nghiệp chúng tôi dự định tham gia vào các mối quan hệ thương mại lâu dài với các đối tác quốc tế.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (115, 'establish', 'Thành lập, thiết lập', 'To set up an organization, system, or set of rules on a firm or permanent basis.', '/ɪˈstæblɪʃ/', 'The board voted to establish clear guidelines for future vendor negotiations.', 'https://api.dictionaryapi.dev/media/pronunciations/en/establish-us.mp3', 'verb', 'Hội đồng quản trị đã bỏ phiếu thiết lập các nguyên tắc rõ ràng cho việc đàm phán với nhà cung cấp trong tương lai.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (116, 'clause', 'Điều khoản trong văn bản luật hoặc hợp đồng', 'A particular and separate article, stipulation, or proviso in a treaty, bill, or contract.', '/klɔːz/', 'The confidentiality clause prevents employees from disclosing proprietary technology.', 'https://api.dictionaryapi.dev/media/pronunciations/en/clause-us.mp3', 'noun', 'Điều khoản bảo mật ngăn nhân viên tiết lộ công nghệ độc quyền.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (117, 'breach', 'Sự vi phạm (hợp đồng, quy định)', 'An act of breaking or failing to observe a law, agreement, or code of conduct.', '/briːtʃ/', 'Failing to deliver the materials within thirty days constitutes a material breach of contract.', 'https://api.dictionaryapi.dev/media/pronunciations/en/breach-us.mp3', 'noun', 'Không bàn giao vật liệu trong vòng ba mươi ngày cấu thành hành vi vi phạm nghiêm trọng hợp đồng.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (118, 'renew', 'Gia hạn, đổi mới', 'To extend the period of validity of an agreement or license.', '/rɪˈnjuː/', 'We plan to renew our software license before the current annual subscription expires.', 'https://api.dictionaryapi.dev/media/pronunciations/en/renew-us.mp3', 'verb', 'Chúng tôi dự định gia hạn giấy phép phần mềm trước khi gói đăng ký năm hiện tại hết hạn.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (119, 'binding', 'Có tính ràng buộc pháp lý', 'Involving an obligation that cannot be broken or legally avoided.', '/ˈbaɪndɪŋ/', 'Once signed by authorized representatives, this document becomes a legally binding contract.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=binding', 'adjective', 'Sau khi được người đại diện có thẩm quyền ký kết, tài liệu này trở thành một hợp đồng ràng buộc pháp lý.', '2026-11-06T16:06:08.256917', '2026-11-06T01:41:11.281366'),
  (120, 'condition', 'Điều kiện, tình trạng', 'A state of affairs that must exist or take place before another thing can be done.', '/kənˈdɪʃən/', 'Payment will only be released under the condition that all goods arrive in perfect shape.', 'https://api.dictionaryapi.dev/media/pronunciations/en/condition-us.mp3', 'noun', 'Khoản thanh toán sẽ chỉ được giải ngân với điều kiện toàn bộ hàng hóa đến nơi trong tình trạng hoàn hảo.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (121, 'compromise', 'Sự thỏa hiệp, sự nhân nhượng', 'An agreement or a settlement of a dispute that is reached by each side making concessions.', '/ˈkɒmprəmaɪz/', 'After hours of debate, both sides reached a fair compromise on warranty coverage.', 'https://api.dictionaryapi.dev/media/pronunciations/en/compromise-uk.mp3', 'noun', 'Sau nhiều giờ thảo luận, cả hai bên đã đạt được thỏa hiệp công bằng về phạm vi bảo hành.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (122, 'liability', 'Trách nhiệm pháp lý, nghĩa vụ bồi thường', 'The state of being responsible for something, especially by law.', '/ˌlaɪəˈbɪlɪti/', 'The shipping company denies any liability for fragile items damaged in heavy weather.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=liability', 'noun', 'Công ty vận chuyển từ chối mọi trách nhiệm pháp lý đối với hàng dễ vỡ bị hư hại do thời tiết xấu.', '2026-11-06T16:06:08.256917', '2026-11-06T01:41:11.281366'),
  (123, 'comply', 'Tuân thủ, làm đúng theo', 'To act in accordance with a wish, request, command, or regulation.', '/kəmˈplaɪ/', 'Every manufacturing plant must strictly comply with national environmental protection laws.', 'https://api.dictionaryapi.dev/media/pronunciations/en/comply-au.mp3', 'verb', 'Mọi nhà máy sản xuất phải tuân thủ nghiêm ngặt các đạo luật bảo vệ môi trường quốc gia.', '2026-11-06T16:06:08.256917', '2026-11-06T01:39:26.888139'),
  (124, 'mutual', 'Lẫn nhau, chung (đôi bên cùng có lợi)', 'Held in common by two or more parties; shared.', '/ˈmjuːtʃuəl/', 'The merger will result in mutual benefits for both corporate entities involved.', 'https://api.dictionaryapi.dev/media/pronunciations/en/mutual-us.mp3', 'adjective', 'Vụ sáp nhập sẽ mang lại lợi ích chung cho cả hai đơn vị doanh nghiệp tham gia.', '2026-11-06T16:06:08.256917', '2026-11-06T01:41:11.281366'),
  (125, 'stipulation', 'Quy định, điều kiện giao kèo', 'A condition or requirement that is specified or demanded as part of an agreement.', '/ˌstɪpjʊˈleɪʃən/', 'One critical stipulation requires that raw materials be sourced from certified organic farms.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=stipulation', 'noun', 'Một điều kiện quy định quan trọng yêu cầu nguyên liệu thô phải được lấy từ các trang trại hữu cơ đạt chuẩn.', '2026-11-06T16:06:08.256917', '2026-11-06T01:41:11.281366'),
  (126, 'attract', 'Thu hút, lôi cuốn khách hàng', 'To cause someone to have a liking for or interest in something.', '/əˈtrækt/', 'The promotional campaign is designed to attract young urban consumers.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=attract', 'verb', 'Chiến dịch khuyến mãi được thiết kế để thu hút đối tượng người tiêu dùng trẻ ở thành thị.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (127, 'compare', 'So sánh, đối chiếu', 'To examine the qualities of two or more things to see how they are similar or different.', '/kəmˈpeə/', 'Customers frequently compare prices online before making an in-store purchase.', 'https://api.dictionaryapi.dev/media/pronunciations/en/compare-us.mp3', 'verb', 'Khách hàng thường xuyên so sánh giá trực tuyến trước khi quyết định mua hàng tại cửa hàng.', '2026-11-06T16:06:26.54648', '2026-11-06T01:39:26.888139'),
  (128, 'competition', 'Sự cạnh tranh, đối thủ cạnh tranh', 'The activity or condition of competing against others in business.', '/ˌkɒmpəˈtɪʃən/', 'Fierce competition in the smartphone sector has driven prices down significantly.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=competition', 'noun', 'Sự cạnh tranh gay gắt trong mảng điện thoại thông minh đã kéo giá giảm đáng kể.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (129, 'consume', 'Tiêu thụ, tiêu dùng', 'To use up a resource, or to buy goods and services.', '/kənˈsjuːm/', 'Households continue to consume higher quantities of energy-efficient electric appliances.', 'https://api.dictionaryapi.dev/media/pronunciations/en/consume-uk.mp3', 'verb', 'Các hộ gia đình tiếp tục tiêu thụ số lượng lớn hơn các thiết bị điện tiết kiệm năng lượng.', '2026-11-06T16:06:26.54648', '2026-11-06T01:39:26.888139'),
  (130, 'convince', 'Thuyết phục', 'To cause someone to believe firmly in the truth of something or to take action.', '/kənˈvɪns/', 'The presentation was persuasive enough to convince investors to fund our startup.', 'https://api.dictionaryapi.dev/media/pronunciations/en/convince-us.mp3', 'verb', 'Bài thuyết trình đủ sức thuyết phục để khiến các nhà đầu tư rót vốn cho dự án khởi nghiệp của chúng tôi.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (131, 'inspire', 'Truyền cảm hứng, tạo động lực', 'To fill someone with the urge or ability to do or feel something creative.', '/ɪnˈspaɪə/', 'The founder’s story helped inspire team members to pursue higher sales targets.', 'https://api.dictionaryapi.dev/media/pronunciations/en/inspire-uk.mp3', 'verb', 'Câu chuyện của người sáng lập đã giúp truyền cảm hứng cho các thành viên trong đội theo đuổi chỉ tiêu doanh số cao hơn.', '2026-11-06T16:06:26.54648', '2026-11-06T01:39:26.888139'),
  (132, 'market', 'Thị trường thương mại', 'An area or arena in which commercial dealings are conducted.', '/ˈmɑːkɪt/', 'Our firm plans to expand its presence into the Southeast Asian market next quarter.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=market', 'noun', 'Công ty chúng tôi dự định mở rộng sự hiện diện vào thị trường Đông Nam Á vào quý tới.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (133, 'persuade', 'Thuyết phục, làm cho tin', 'To induce someone to do something through reasoning or argument.', '/pəˈsweɪd/', 'The sales representative tried hard to persuade the client to upgrade their service package.', 'https://api.dictionaryapi.dev/media/pronunciations/en/persuade-us.mp3', 'verb', 'Đại diện bán hàng đã nỗ lực thuyết phục khách hàng nâng cấp gói dịch vụ của họ.', '2026-11-06T16:06:26.54648', '2026-11-06T01:39:26.888139'),
  (134, 'productive', 'Năng suất, hiệu quả', 'Producing or achieving significant results or output.', '/prəˈdʌktɪv/', 'The focus group discussion proved to be very productive for product design refinement.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=productive', 'adjective', 'Buổi thảo luận nhóm tập trung đã chứng minh mang lại hiệu quả cao cho việc tinh chỉnh thiết kế sản phẩm.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (135, 'satisfy', 'Làm hài lòng, đáp ứng nhu cầu', 'To meet the expectations, needs, or desires of someone.', '/ˈsætɪsfaɪ/', 'Our new customer warranty program aims to satisfy even the most demanding shoppers.', 'https://api.dictionaryapi.dev/media/pronunciations/en/satisfy-us.mp3', 'verb', 'Chương trình bảo hành khách hàng mới của chúng tôi nhằm làm hài lòng ngay cả những người mua hàng khó tính nhất.', '2026-11-06T16:06:26.54648', '2026-11-06T01:39:26.888139'),
  (136, 'campaign', 'Chiến dịch (quảng bá, tiếp thị)', 'An organized course of action to achieve a particular marketing goal.', '/kæmˈpeɪn/', 'The holiday advertising campaign generated record-breaking revenue for the brand.', 'https://api.dictionaryapi.dev/media/pronunciations/en/campaign-us.mp3', 'noun', 'Chiến dịch quảng cáo dịp lễ đã mang lại doanh thu kỷ lục cho thương hiệu.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (137, 'launch', 'Ra mắt, tung ra (sản phẩm mới)', 'To introduce a new product or service onto the market.', '/lɔːntʃ/', 'The electronics maker is getting ready to launch its flagship camera next week.', 'https://api.dictionaryapi.dev/media/pronunciations/en/launch-us.mp3', 'verb', 'Nhà sản xuất đồ điện tử đang sẵn sàng ra mắt mẫu máy ảnh cao cấp chủ lực vào tuần tới.', '2026-11-06T16:06:26.54648', '2026-11-06T01:39:26.888139'),
  (138, 'promote', 'Quảng bá, thúc đẩy tiêu thụ', 'To publicize or advertise a product or service in order to increase sales.', '/prəˈməʊt/', 'Celebrity endorsements are frequently used to promote new luxury cosmetic lines.', 'https://api.dictionaryapi.dev/media/pronunciations/en/promote-us.mp3', 'verb', 'Người nổi tiếng thường xuyên được mời để quảng bá cho các dòng mỹ phẩm cao cấp mới.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (139, 'discount', 'Khoản giảm giá, chiết khấu', 'A deduction from the usual cost of something.', '/ˈdɪskaʊnt/', 'Members of the loyalty club receive a fifteen percent discount on all items.', 'https://api.dictionaryapi.dev/media/pronunciations/en/discount-uk.mp3', 'noun', 'Thành viên câu lạc bộ khách hàng thân thiết được giảm giá mười lăm phần trăm cho tất cả mặt hàng.', '2026-11-06T16:06:26.54648', '2026-11-06T01:39:26.888139'),
  (140, 'brand', 'Thương hiệu, nhãn hiệu', 'A type of product manufactured by a particular company under a particular name.', '/brænd/', 'Building strong brand equity requires consistent product quality and honest marketing.', 'https://api.dictionaryapi.dev/media/pronunciations/en/brand-us.mp3', 'noun', 'Việc xây dựng giá trị thương hiệu vững mạnh đòi hỏi chất lượng sản phẩm nhất quán và tiếp thị trung thực.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (141, 'customer', 'Khách hàng', 'A person or organization that buys goods or services from a store or business.', '/ˈkʌstəmə/', 'Delivering exceptional customer service is our top operational priority every single day.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=customer', 'noun', 'Mang đến dịch vụ khách hàng xuất sắc là ưu tiên hoạt động hàng đầu của chúng tôi mỗi ngày.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (142, 'demand', 'Nhu cầu thị trường', 'The desire of purchasers, consumers, or clients for a particular commodity or service.', '/dɪˈmɑːnd/', 'Consumer demand for organic groceries has risen substantially in urban regions.', 'https://api.dictionaryapi.dev/media/pronunciations/en/demand-us.mp3', 'noun', 'Nhu cầu của người tiêu dùng đối với thực phẩm hữu cơ đã tăng đáng kể tại các khu vực đô thị.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (143, 'strategy', 'Chiến lược, kế hoạch hành động', 'A plan of action designed to achieve a long-term or overall aim.', '/ˈstrætədʒi/', 'The executive committee met to formulate an aggressive digital marketing strategy.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=strategy', 'noun', 'Ban điều hành đã họp để xây dựng một chiến lược tiếp thị số quyết liệt.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (144, 'retail', 'Bán lẻ', 'The sale of goods to the public in relatively small quantities for use or consumption.', '/ˈriːteɪl/', 'Online retail sales surpassed brick-and-mortar storefront revenue this quarter.', 'https://api.dictionaryapi.dev/media/pronunciations/en/retail-us.mp3', 'noun', 'Doanh số bán lẻ trực tuyến đã vượt qua doanh thu của các cửa hàng truyền thống trong quý này.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (145, 'wholesale', 'Bán buôn, bán sỉ', 'The selling of goods in large quantities to be retailed by others.', '/ˈhəʊlseɪl/', 'By purchasing coffee beans at wholesale prices, the café chain lowered production costs.', 'https://api.dictionaryapi.dev/media/pronunciations/en/wholesale-us.mp3', 'noun', 'Bằng cách mua hạt cà phê với giá bán buôn, chuỗi quán cà phê đã hạ được chi phí sản xuất.', '2026-11-06T16:06:26.54648', '2026-11-06T01:39:26.888139'),
  (146, 'brochure', 'Tờ gấp giới thiệu sản phẩm/dịch vụ', 'A small book or magazine containing pictures and information about a product or service.', '/ˈbrəʊʃə/', 'The travel agency handed out an informative brochure showcasing resort packages.', 'https://api.dictionaryapi.dev/media/pronunciations/en/brochure-us.mp3', 'noun', 'Đại lý du lịch đã phát một cuốn cẩm nang giới thiệu đầy đủ thông tin về các gói nghỉ dưỡng.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (147, 'flyer', 'Tờ rơi quảng cáo', 'A small handbill advertising an event or product.', '/ˈflaɪə/', 'Promotional staff distributed a glossy flyer announcing the grand store opening.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=flyer', 'noun', 'Nhân viên quảng bá đã phát tờ rơi bóng bẩy thông báo lễ khai trương cửa hàng.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (148, 'purchase', 'Mua, tậu sắm', 'To acquire something by paying for it; to buy.', '/ˈpɜːtʃəs/', 'Patrons who purchase any laptop receive a complimentary protective carrying case.', 'https://api.dictionaryapi.dev/media/pronunciations/en/purchase-us.mp3', 'verb', 'Những khách hàng mua bất kỳ máy tính xách tay nào sẽ nhận được túi đựng bảo vệ miễn phí.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (149, 'display', 'Sự trưng bày, kệ hàng mẫu', 'A public exhibition of something or an arrangement of goods for sale.', '/dɪˈspleɪ/', 'The window display showcases the latest autumn apparel collections prominently.', 'https://api.dictionaryapi.dev/media/pronunciations/en/display-us.mp3', 'noun', 'Tủ kính trưng bày làm nổi bật các bộ sưu tập trang phục mùa thu mới nhất.', '2026-11-06T16:06:26.54648', '2026-11-06T01:39:26.888139'),
  (150, 'rebate', 'Khoản hoàn tiền sau mua (chiết khấu lại)', 'A partial refund to someone who has paid too much money for tax, rent, or a utility.', '/ˈriːbeɪt/', 'Customers who submitted the rebate coupon received a fifty-dollar refund check.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=rebate', 'noun', 'Những khách hàng gửi phiếu hoàn tiền đã nhận được tấm séc hoàn trả năm mươi đô la.', '2026-11-06T16:06:26.54648', '2026-11-06T01:41:11.281366'),
  (476, 'shipment', 'Lô hàng, chuyến hàng vận chuyển', 'An amount of goods shipped or transported together.', '/ˈʃɪpmənt/', 'The international shipment of auto components arrived at the port this morning.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=shipment', 'noun', 'Lô hàng linh kiện ô tô quốc tế đã cập cảng vào sáng nay.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (477, 'warehouse', 'Nhà kho, kho chứa hàng', 'A large building where raw materials or manufactured goods may be stored prior to distribution.', '/ˈweəhaʊs/', 'Finished electronics are stored securely in a temperature-controlled central warehouse.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=warehouse', 'noun', 'Các thiết bị điện tử hoàn thiện được lưu trữ an toàn trong một nhà kho trung tâm có kiểm soát nhiệt độ.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (478, 'courier', 'Người đưa thư, dịch vụ chuyển phát nhanh', 'A company or employee that transports parcels and documents rapidly.', '/ˈkʊriə/', 'We dispatched the signed legal contracts via an express courier service.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=courier', 'noun', 'Chúng tôi đã gửi các hợp đồng pháp lý đã ký thông qua dịch vụ chuyển phát nhanh.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (479, 'cargo', 'Hàng hóa vận chuyển (đường biển, đường hàng không)', 'Goods carried on a ship, aircraft, or motor vehicle.', '/ˈkɑːɡəʊ/', 'The freight airliner has sufficient capacity to transport eighty tons of commercial cargo.', 'https://api.dictionaryapi.dev/media/pronunciations/en/cargo-us.mp3', 'noun', 'Chiếc máy bay vận tải hàng hóa có đủ sức chứa để vận chuyển tám mươi tấn hàng hóa thương mại.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (480, 'freight', 'Cước phí vận chuyển, hàng hóa chuyên chở', 'Goods transported in bulk by truck, train, ship, or aircraft.', '/freɪt/', 'Shipping goods by rail freight is generally more economical than road transport over long hauls.', 'https://api.dictionaryapi.dev/media/pronunciations/en/freight-us.mp3', 'noun', 'Vận chuyển hàng hóa bằng đường sắt nhìn chung tiết kiệm hơn đường bộ trên các tuyến đường dài.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (481, 'transit', 'Sự quá cảnh, sự trung chuyển hàng hóa', 'The carrying of people, goods, or materials from one place to another.', '/ˈtrænzɪt/', 'The fragile ceramics were wrapped in bubble wrap so they would not break in transit.', 'https://api.dictionaryapi.dev/media/pronunciations/en/transit-us.mp3', 'noun', 'Những món đồ gốm dễ vỡ đã được bọc màng xốp hơi để không bị vỡ trong quá trình trung chuyển.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (482, 'delivery', 'Sự giao hàng, việc phân phát hàng', 'The action of delivering letters, packages, or ordered goods.', '/dɪˈlɪvəri/', 'Standard delivery takes between three to five business days across the country.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=delivery', 'noun', 'Giao hàng tiêu chuẩn mất từ ba đến năm ngày làm việc trên toàn quốc.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (483, 'carrier', 'Hãng vận chuyển, đơn vị chuyên chở', 'A company that undertakes the professional transport of goods or passengers.', '/ˈkæriə/', 'The merchant partners with a reputable carrier to ensure dependable parcel dispatch.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=carrier', 'noun', 'Thương nhân hợp tác với một đơn vị vận chuyển uy tín để đảm bảo việc gửi bưu kiện đáng tin cậy.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (484, 'track', 'Theo dõi lộ trình (đơn hàng)', 'To follow the progress or location of something continuously.', '/træk/', 'Shoppers can track the live status of their order using the unique reference code provided.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=track', 'verb', 'Người mua sắm có thể theo dõi tình trạng trực tiếp đơn hàng bằng mã tham chiếu duy nhất được cung cấp.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (485, 'logistics', 'Hậu cần, quản lý chuỗi cung ứng logistics', 'The detailed coordination of a complex operation involving many people, facilities, or supplies.', '/ləˈdʒɪstɪks/', 'Our logistics supervisor implemented new automated routing software to decrease fuel consumption.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=logistics', 'noun', 'Giám sát hậu cần của chúng tôi đã triển khai phần mềm định tuyến tự động mới để giảm tiêu hao nhiên liệu.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (487, 'dispatch', 'Gửi đi, phái đi (hàng hóa, bưu kiện)', 'To send off to a destination or for a purpose.', '/dɪˈspætʃ/', 'Orders confirmed prior to noon are dispatched from the distribution depot on the same day.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=dispatch', 'verb', 'Những đơn hàng được xác nhận trước buổi trưa sẽ được gửi đi từ kho phân phối ngay trong ngày.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (488, 'package', 'Kiện hàng, gói hàng bưu phẩm', 'An object or group of objects wrapped in paper or packed in a box.', '/ˈpækɪdʒ/', 'The courier delivered a heavy package containing engineering replacement parts.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=package', 'noun', 'Người giao hàng đã giao một gói hàng nặng chứa các phụ tùng thay thế kỹ thuật.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (489, 'container', 'Thùng container chứa hàng', 'A large metal box of standard design for shipping goods across rail, truck, and sea.', '/kənˈteɪnə/', 'Cranes lifted each shipping container smoothly onto the oceanic vessel.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=container', 'noun', 'Cần cẩu đã nhấc từng thùng container chở hàng nhẹ nhàng lên con tàu viễn dương.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (490, 'export', 'Xuất khẩu', 'To send goods or services to another country for sale.', '/ɪkˈspɔːt/', 'Vietnam continues to export significant quantities of high-grade coffee and rice.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=export', 'verb', 'Việt Nam tiếp tục xuất khẩu khối lượng đáng kể cà phê và gạo chất lượng cao.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (491, 'import', 'Nhập khẩu', 'To bring goods or services into a country from abroad for sale.', '/ɪmˈpɔːt/', 'The domestic automaker needs to import specialized microchips from overseas suppliers.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=import', 'verb', 'Nhà sản xuất ô tô trong nước cần nhập khẩu các vi mạch chuyên dụng từ các nhà cung cấp nước ngoài.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (492, 'fragile', 'Dễ vỡ, mỏng manh', 'Easily broken or damaged.', '/ˈfrædʒaɪl/', 'Boxes with glassware are prominently stamped with a red fragile warning label.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=fragile', 'adjective', 'Các thùng chứa đồ thủy tinh được đóng nổi bật nhãn cảnh báo hàng dễ vỡ màu đỏ.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (493, 'distributor', 'Nhà phân phối hàng hóa', 'An agent or business that supplies goods to stores and other businesses.', '/dɪˈstrɪbjʊtə/', 'The beverage producer signed an exclusive deal with a nationwide distributor.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=distributor', 'noun', 'Nhà sản xuất đồ uống đã ký hợp đồng độc quyền với một nhà phân phối trên toàn quốc.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (494, 'recipient', 'Người nhận (bưu phẩm, hàng gửi)', 'A person or thing that receives something.', '/rɪˈsɪpiənt/', 'The driver requested a signature from the designated recipient before handing over the envelope.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=recipient', 'noun', 'Tài xế đã yêu cầu chữ ký của người nhận được chỉ định trước khi trao chiếc phong bì.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (495, 'express', 'Hỏa tốc, cấp tốc', 'Operating at high speed or without making intermediate stops; rapid delivery.', '/ɪkˈspres/', 'Selecting express delivery ensures your medical supplies will arrive early the next morning.', 'https://api.dictionaryapi.dev/media/pronunciations/en/express-us.mp3', 'adjective', 'Lựa chọn chuyển phát hỏa tốc đảm bảo đồ tiếp tế y tế của bạn sẽ đến nơi vào đầu giờ sáng hôm sau.', '2026-11-06T01:39:26.888139', '2026-11-06T01:39:26.888139'),
  (496, 'haul', 'Chở, kéo hàng khối lượng lớn', 'To pull or transport with effort or in a vehicle over a distance.', '/hɔːl/', 'Heavy trucks haul industrial gravel directly from the quarry to the construction yard.', 'https://api.dictionaryapi.dev/media/pronunciations/en/haul-au.mp3', 'verb', 'Xe tải hạng nặng chở sỏi công nghiệp trực tiếp từ mỏ đá đến bãi công trường.', '2026-11-06T01:39:26.888139', '2026-11-06T01:39:26.888139'),
  (497, 'delay', 'Sự chậm trễ, sự trì hoãn', 'A period of time by which something is late or postponed.', '/dɪˈleɪ/', 'A sudden blizzard caused a three-day freight delay across regional rail corridors.', 'https://api.dictionaryapi.dev/media/pronunciations/en/delay-1-us.mp3', 'noun', 'Trận bão tuyết bất ngờ đã gây ra sự chậm trễ vận chuyển hàng hóa kéo dài ba ngày trên các tuyến đường sắt khu vực.', '2026-11-06T01:39:26.888139', '2026-11-06T01:39:26.888139'),
  (498, 'loading', 'Việc bốc dỡ hàng lên xe/tàu', 'The process of putting goods onto a vehicle, aircraft, or ship.', '/ˈləʊdɪŋ/', 'Forklift operators must wear protective hard hats inside the loading dock area.', 'https://api.dictionaryapi.dev/media/pronunciations/en/loading-au.mp3', 'noun', 'Những người vận hành xe nâng phải đội mũ bảo hộ lao động bên trong khu vực bốc dỡ hàng.', '2026-11-06T01:39:26.888139', '2026-11-06T01:39:26.888139'),
  (499, 'consignment', 'Lô hàng gửi bán, hàng ký gửi', 'A batch of goods destined for or delivered to someone.', '/kənˈsaɪnmənt/', 'The boutique agreed to sell high-end silk scarves on a consignment basis.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=consignment', 'noun', 'Cửa hàng thời trang đã đồng ý bán khăn lụa cao cấp theo hình thức ký gửi.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (500, 'dock', 'Bến tàu, cầu cảng bốc dỡ hàng', 'An enclosed area of water in a port for the loading, unloading, and repair of ships.', '/dɒk/', 'The cargo vessel remained docked at berth four while workers unloaded containers.', 'https://api.dictionaryapi.dev/media/pronunciations/en/dock-us.mp3', 'noun', 'Con tàu chở hàng vẫn neo đậu tại bến số bốn trong khi công nhân bốc dỡ các container.', '2026-11-06T01:39:26.888139', '2026-11-06T01:39:26.888139'),
  (526, 'complaint', 'Lời phàn nàn, sự khiếu nại', 'A statement that something is unsatisfactory or unacceptable.', '/kəmˈpleɪnt/', 'The customer service department logged a formal complaint regarding delayed product delivery.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=complaint', 'noun', 'Bộ phận dịch vụ khách hàng đã ghi nhận một lời khiếu nại chính thức liên quan đến việc giao sản phẩm chậm trễ.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (527, 'inquiry', 'Yêu cầu hỏi thông tin, thắc mắc', 'An act of asking for information.', '/ɪnˈkwaɪəri/', 'Our support team strives to respond to every online customer inquiry within four hours.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=inquiry', 'noun', 'Đội ngũ hỗ trợ của chúng tôi nỗ lực trả lời mọi thắc mắc trực tuyến của khách hàng trong vòng bốn giờ.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (528, 'refund', 'Khoản tiền hoàn lại', 'A repayment of a sum of money, typically to a dissatisfied customer.', '/ˈriːfʌnd/', 'The store issued a full refund after the customer returned the unopened merchandise.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=refund', 'noun', 'Cửa hàng đã hoàn lại toàn bộ số tiền sau khi khách hàng trả lại món hàng chưa mở nắp.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (529, 'exchange', 'Đổi hàng (lấy cỡ, màu hoặc mẫu khác)', 'To give something and receive something of the same kind in return.', '/ɪksˈtʃeɪndʒ/', 'You can exchange the shirt for a larger size within fourteen days of purchase.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=exchange', 'verb', 'Bạn có thể đổi chiếc áo sơ mi lấy kích cỡ lớn hơn trong vòng mười bốn ngày kể từ ngày mua.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (530, 'feedback', 'Ý kiến phản hồi, đánh giá của người dùng', 'Information about reactions to a product or a person’s performance of a task.', '/ˈfiːdbæk/', 'Positive customer feedback encouraged management to expand our weekend store hours.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=feedback', 'noun', 'Những phản hồi tích cực của khách hàng đã khích lệ ban quản lý mở rộng giờ mở cửa cửa hàng vào cuối tuần.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (531, 'satisfaction', 'Sự hài lòng, sự thỏa mãn', 'Fulfillment of one’s wishes, expectations, or needs, or the pleasure derived from this.', '/ˌsætɪsˈfækʃən/', 'Client satisfaction ratings jumped by twenty percent after the recent website redesign.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=satisfaction', 'noun', 'Tỷ lệ hài lòng của khách hàng đã tăng thêm hai mươi phần trăm sau đợt thiết kế lại trang web gần đây.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (532, 'guarantee', 'Sự cam kết, bảo đảm chắc chắn', 'A formal promise or assurance that certain conditions will be fulfilled.', '/ˌɡærənˈtiː/', 'The maker provides a money-back guarantee if customers are not completely satisfied.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=guarantee', 'noun', 'Nhà sản xuất đưa ra cam kết hoàn tiền nếu khách hàng không hoàn toàn hài lòng.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (533, 'warranty', 'Phiếu/chính sách bảo hành sản phẩm', 'A written guarantee issued to the purchaser of an article, promising repair or replacement if necessary.', '/ˈwɒrənti/', 'The laptop is backed by a comprehensive two-year manufacturer warranty covering internal hardware.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=warranty', 'noun', 'Máy tính xách tay được hỗ trợ bởi gói bảo hành toàn diện hai năm của nhà sản xuất bao gồm phần cứng bên trong.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (534, 'policy', 'Chính sách, quy định', 'A course or principle of action adopted or proposed by an organization or individual.', '/ˈpɒlɪsi/', 'Under our exchange policy, sale items discounted over fifty percent cannot be returned.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=policy', 'noun', 'Theo chính sách đổi hàng của chúng tôi, các mặt hàng giảm giá trên năm mươi phần trăm không được hoàn trả.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (535, 'representative', 'Đại diện (chăm sóc khách hàng, bán hàng)', 'A person chosen or appointed to act or speak for another or others.', '/ˌreprɪˈzentətɪv/', 'A helpful customer service representative walked the caller through the account activation steps.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=representative', 'noun', 'Một đại diện chăm sóc khách hàng nhiệt tình đã hướng dẫn người gọi qua các bước kích hoạt tài khoản.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (536, 'promptly', 'Kịp thời, nhanh chóng, ngay tức thì', 'With little or no delay; immediately.', '/ˈprɒmptli/', 'Our technical support team acted promptly to fix the database synchronization error.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=promptly', 'adverb', 'Đội ngũ hỗ trợ kỹ thuật của chúng tôi đã hành động nhanh chóng để khắc phục lỗi đồng bộ hóa cơ sở dữ liệu.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (537, 'courtesy', 'Sự lịch thiệp, nhã nhặn', 'The showing of politeness in one’s attitude and behavior toward others.', '/ˈkɜːtəsi/', 'Treating callers with courtesy and patience is an essential skill for all hotline agents.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=courtesy', 'noun', 'Đối xử với người gọi bằng sự lịch sự và kiên nhẫn là kỹ năng thiết yếu đối với mọi điện thoại viên đường dây nóng.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (538, 'response', 'Câu trả lời, lời phản hồi', 'A verbal or written answer.', '/rɪˈspɒns/', 'You will receive an automated email response confirming receipt of your inquiry form.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=response', 'noun', 'Bạn sẽ nhận được một phản hồi email tự động xác nhận đã nhận được mẫu yêu cầu của bạn.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (539, 'dissatisfaction', 'Sự không hài lòng, thất vọng', 'Lack of satisfaction; disappointment or unhappiness with quality.', '/dɪsˌsætɪsˈfækʃən/', 'The hotel manager offered a complimentary meal voucher to soothe customer dissatisfaction.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=dissatisfaction', 'noun', 'Quản lý khách sạn đã tặng phiếu giảm giá bữa ăn miễn phí để xoa dịu sự không hài lòng của khách hàng.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (540, 'address', 'Giải quyết, xử lý (vấn đề, lo ngại)', 'To think about and begin to deal with an issue or problem.', '/əˈdres/', 'Management promised to address employee safety concerns during the next town hall meeting.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=address', 'verb', 'Ban quản lý hứa sẽ giải quyết những lo ngại về an toàn của nhân viên trong cuộc họp toàn thể tiếp theo.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (541, 'assistance', 'Sự hỗ trợ, trợ giúp', 'The action of helping someone by sharing work or providing resources.', '/əˈsɪstəns/', 'Do not hesitate to contact our helpline if you need further assistance with installation.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=assistance', 'noun', 'Đừng ngần ngại liên hệ đường dây trợ giúp của chúng tôi nếu bạn cần hỗ trợ thêm về việc cài đặt.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (542, 'support', 'Hỗ trợ kỹ thuật, dịch vụ hỗ trợ', 'Assistance or encouragement given to someone, or customer technical aid.', '/səˈpɔːt/', 'Subscribers enjoy around-the-clock technical support via live chat or phone.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=support', 'noun', 'Những người đăng ký được hưởng dịch vụ hỗ trợ kỹ thuật suốt ngày đêm qua trò chuyện trực tiếp hoặc điện thoại.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (543, 'hotline', 'Đường dây nóng hỗ trợ khẩn cấp', 'A direct telephone line set up for a specific purpose, especially in emergencies.', '/ˈhɒtlaɪn/', 'Dial our toll-free customer hotline if you notice any suspicious account activity.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=hotline', 'noun', 'Hãy gọi đến đường dây nóng miễn cước của chúng tôi nếu bạn nhận thấy bất kỳ hoạt động tài khoản đáng ngờ nào.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (544, 'replacement', 'Sản phẩm thay thế, người thay thế', 'A person or thing that takes the place of another.', '/rɪˈpleɪsmənt/', 'The retailer promptly dispatched a free replacement unit for the damaged microwave oven.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=replacement', 'noun', 'Nhà bán lẻ đã nhanh chóng gửi một chiếc lò vi sóng thay thế miễn phí cho chiếc bị hư hỏng.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (545, 'maintenance', 'Sự bảo dưỡng, bảo trì thiết bị', 'The process of maintaining or preserving someone or something.', '/ˈmeɪntənəns/', 'Routine elevator maintenance is conducted on the first Sunday of every month.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=maintenance', 'noun', 'Việc bảo trì thang máy định kỳ được tiến hành vào ngày Chủ Nhật đầu tiên của mỗi tháng.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (546, 'defective', 'Bị lỗi, có khuyết tật', 'Imperfect or faulty; having a flaw.', '/dɪˈfektɪv/', 'The manufacturer recalled twenty thousand cars due to a potentially defective airbag sensor.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=defective', 'adjective', 'Nhà sản xuất đã thu hồi hai mươi nghìn chiếc ô tô do cảm biến túi khí có khả năng bị lỗi.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (547, 'apologize', 'Xin lỗi, tạ lỗi', 'To express regret for something that one has done wrong.', '/əˈpɒlədʒaɪz/', 'We sincerely apologize for any inconvenience caused by our server outage yesterday.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=apologize', 'verb', 'Chúng tôi chân thành xin lỗi vì bất kỳ sự bất tiện nào do sự cố ngừng hoạt động của máy chủ ngày hôm qua.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (548, 'compensate', 'Bồi thường, đền bù thiệt hại', 'To give someone something, typically money, in recognition of loss, suffering, or injury.', '/ˈkɒmpənseɪt/', 'The airline provided hotel vouchers to compensate passengers stranded overnight.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=compensate', 'verb', 'Hãng hàng không đã cung cấp phiếu khách sạn để bồi thường cho những hành khách bị mắc kẹt qua đêm.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (549, 'technician', 'Kỹ thuật viên', 'A person employed to look after technical equipment or do practical work in a laboratory.', '/tekˈnɪʃən/', 'A certified technician will arrive between two and four o’clock to repair the printer.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=technician', 'noun', 'Một kỹ thuật viên có chứng chỉ sẽ đến trong khoảng từ hai đến bốn giờ để sửa máy in.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366'),
  (550, 'clarification', 'Sự làm rõ, lời giải thích rõ ràng', 'The action of making a statement or situation less confused and more comprehensible.', '/ˌklærɪfɪˈkeɪʃən/', 'The client asked for clarification regarding the billing terms listed on the invoice.', 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=clarification', 'noun', 'Khách hàng yêu cầu làm rõ các điều khoản thanh toán được liệt kê trên hóa đơn.', '2026-11-06T01:39:26.888139', '2026-11-06T01:41:11.281366')
